import math
F=Fig('arrow146');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
N={'Heat energy causes':('حرارتی توانائی','تودوخیزه انرژي'),'more collisions':('خامرے اور سبسٹریٹ','د انزایم او سبسټرېټ'),'between enzyme':('کے درمیان زیادہ','ترمنځ ډېرې'),'and substrate':('تصادم پیدا کرتی ہے','ټکرې رامنځته کوي'),
   'Optimum temperature':('انسانوں کے لیے موزوں','د انسانانو لپاره'),'for humans is':('ترین درجہ حرارت','غوره تودوخه'),'close to 37°C':('37°C کے قریب ہے','37°C ته نږدې ده'),
   'Enzymes denature':('زیادہ درجہ حرارت پر','په لوړه تودوخه'),'at high':('خامرے ڈی نیچر ہوتے','انزایمونه ډینېچر کېږي'),'temperatures':('ہیں اس لیے شرح','نو کچه'),'so rate falls rapidly':('تیزی سے گرتی ہے','په چټکۍ ټیټېږي'),
   'Rate of reaction':('تعامل کی شرح','د تعامل کچه'),'Temperature (°C)':('درجہ حرارت (°C)','تودوخه (°C)')}
def lb(lang,v):return v if lang=='en' else N[v][0 if lang=='ur' else 1]
def graph(lang):
 X=lambda T:180+T*8;Y=lambda r:330-r*2.2
 s=F.start(400)
 for i in range(0,61,5):s+=line(X(i),Y(0),X(i),Y(100),0.6,'#bbb')
 for r in range(0,101,10):s+=line(X(0),Y(r),X(65),Y(r),0.6,'#bbb')
 s+=line(X(0),Y(0),X(65),Y(0),2)+line(X(0),Y(0),X(0),Y(100),2)
 for T in range(0,61,10):s+=t(X(T),Y(0)+20,str(T),12)
 pts=[]
 for T10 in range(0,601):
  T=T10/10
  r=100*math.exp(-((T-40)/14)**2) if T<=40 else max(0,100*(1-((T-40)/20)**2))
  if T<=40:r=100*(T/40)**1.8
  pts.append(f'{X(T):.1f},{Y(r):.1f}')
 s+=f'<polyline points="{" ".join(pts)}" fill="none" stroke="#00897b" stroke-width="2.5"/>'+line(X(37),Y(0),X(37),Y(104),1.5,'#222','stroke-dasharray="3 4"')
 s+=f'<text x="{X(0)-30}" y="{Y(50)}" transform="rotate(-90 {X(0)-30} {Y(50)})" text-anchor="middle" font-family="Arial" font-size="13" fill="#ad1457">{lb(lang,"Rate of reaction")}</text>'+t(X(32),Y(0)+40,lb(lang,'Temperature (°C)'),13,'#ad1457')
 bx=lambda x,y,ls:f'<rect x="{x-80}" y="{y-14}" width="160" height="{16*len(ls)+10}" fill="#fce4ec" stroke="#c2185b"/>'+''.join(t(x,y+16*k,lb(lang,v),11) for k,v in enumerate(ls))
 s+=bx(X(8),20,['Heat energy causes','more collisions','between enzyme','and substrate'])+line(X(8),94,X(8),130)+line(X(8),130,X(25),Y(100*(25/40)**1.8))
 s+=bx(X(37),30,['Optimum temperature','for humans is','close to 37°C'])
 s+=bx(X(60),20,['Enzymes denature','at high','temperatures','so rate falls rapidly'])+line(X(60),94,X(60),130)+line(X(60),130,X(50),Y(100*(1-(10/20)**2)))
 return s+'</svg>'

add('ii. In the Digestion of Fats','ii. چکنائیوں کے ہضم میں','ii. د غوړیو په هضم کې','heading')
add('There is only slight hydrolysis of fats in the mouth and stomach because no lipase is secreted by the salivary glands while the lipase of the gastric juice is weak and can hydrolysed only small fat molecules. The lingual lipase enzyme secreted by the Ebner’s glands on the dorsum of the tongue remains active in stomach and can hydrolyse or digest about 30% of the ingested fats. When the fats reach the intestine, they face pancreatic juice. This juice contains a pancreatic lipase enzyme also known as steapsin. This enzyme completely hydrolyses or digests all the fats of the food.',
 'منہ اور معدے میں چکنائیوں کی صرف معمولی ہائیڈرولائسز ہوتی ہے کیونکہ لعابی غدود کوئی لائپیز خارج نہیں کرتے جبکہ معدے کے رس کا لائپیز کمزور ہے اور صرف چکنائی کے چھوٹے سالمات کو ہائیڈرولائز کر سکتا ہے۔ زبان کی پشت پر ایبنر کے غدود سے خارج ہونے والا لسانی لائپیز خامرہ معدے میں فعال رہتا ہے اور نگلی گئی چکنائیوں کے تقریباً 30% کو ہائیڈرولائز یا ہضم کر سکتا ہے۔ جب چکنائیاں آنت تک پہنچتی ہیں تو لبلبے کے رس سے سامنا ہوتا ہے۔ اس رس میں لبلبی لائپیز خامرہ ہوتا ہے جسے سٹیپسن بھی کہتے ہیں۔ یہ خامرہ خوراک کی تمام چکنائیوں کو مکمل طور پر ہائیڈرولائز یا ہضم کر دیتا ہے۔',
 'په خوله او معده کې د غوړیو یوازې لږ هایدرولایسس کېږي ځکه د لاړو غدې لایپېز نه افرازوي، په داسې حال کې چې د معدې د شیرې لایپېز کمزوری دی او یوازې د غوړیو کوچني مالیکولونه هایدرولایز کولی شي. د ژبې پر شا د ایبنر له غدو افراز شوی ژبنی لایپېز انزایم په معده کې فعال پاتې کېږي او د تېر شویو غوړیو نږدې 30% هایدرولایز یا هضمولی شي. کله چې غوړي کولمو ته ورسېږي، له پانقراسي شیرې سره مخ کېږي. دا شیره د پانقراس لایپېز انزایم لري چې سټیپسین هم بلل کېږي. دا انزایم د خوړو ټول غوړي په بشپړ ډول هایدرولایز یا هضموي.')
add('iii. In the Digestion of Proteins','iii. پروٹینز کے ہضم میں','iii. د پروټینونو په هضم کې','heading')
add('Digestion of proteins starts in stomach because the saliva contains no enzyme for the digestion of proteins. The first enzyme that acts upon the proteins of the ingested food is called pepsin present in the gastric juice of stomach. It is best active in acidic pH of 1–2 range. Pepsin has also milk-curdling properties.','پروٹینز کا ہضم معدے میں شروع ہوتا ہے کیونکہ لعاب میں پروٹینز کے ہضم کا کوئی خامرہ نہیں ہوتا۔ نگلی گئی خوراک کے پروٹینز پر عمل کرنے والا پہلا خامرہ پیپسن کہلاتا ہے جو معدے کے رس میں موجود ہوتا ہے۔ یہ 1–2 کی حد کے تیزابی pH میں بہترین فعال ہے۔ پیپسن میں دودھ جمانے کی خصوصیات بھی ہیں۔','د پروټینونو هضم په معده کې پیلېږي ځکه لاړې د پروټینونو د هضم لپاره هېڅ انزایم نه لري. لومړی انزایم چې د تېرو شویو خوړو پر پروټینونو عمل کوي پېپسین بلل کېږي چې د معدې په شیره کې شته. د 1–2 په اسیدي pH کې تر ټولو ښه فعال دی. پېپسین د شیدو د پرېړ کولو ځانګړنې هم لري.')
add('When food enters the intestine, pancreatic juice comes into action. This juice contains numerous enzymes for the digestion of proteins. These enzymes include trypsin, chemotrypsin. These enzymes are secreted in their inactive forms, which are then activated, by the action of other enzymes. For example, the inactive trypsinogen is activated to active trypsin by the action of enzyme enterokinase. Besides, trypsin and chymotrypsin pancreatic juice contains carboxypeptidase’s A and B, elastase, collagenase etc.','جب خوراک آنت میں داخل ہوتی ہے تو لبلبے کا رس عمل میں آتا ہے۔ اس رس میں پروٹینز کے ہضم کے لیے بہت سے خامرے ہوتے ہیں۔ ان خامروں میں ٹرپسن، کائموٹرپسن شامل ہیں۔ یہ خامرے اپنی غیر فعال صورتوں میں خارج ہوتے ہیں جو پھر دوسرے خامروں کے عمل سے فعال ہوتے ہیں۔ مثلاً غیر فعال ٹرپسینوجن خامرہ اینٹرو کائنیز کے عمل سے فعال ٹرپسن میں بدل جاتا ہے۔ ٹرپسن اور کائموٹرپسن کے علاوہ لبلبے کے رس میں کاربوکسی پیپٹیڈیز A اور B، ایلاسٹیز، کولیجینیز وغیرہ ہوتے ہیں۔','کله چې خواړه کولمو ته ننوځي، پانقراسي شیره په کار لوېږي. دا شیره د پروټینونو د هضم لپاره ډېر انزایمونه لري. په دې انزایمونو کې ټرپسین، کایموټرپسین شامل دي. دا انزایمونه په خپلو غیر فعالو بڼو افرازېږي چې بیا د نورو انزایمونو د عمل په واسطه فعالېږي. د بېلګې په توګه غیر فعال ټرپسینوجن د انټروکاینېز انزایم د عمل په واسطه په فعال ټرپسین بدلېږي. سربېره پر ټرپسین او کایموټرپسین، پانقراسي شیره کاربوکسي پېپټیډېز A او B، الاسټېز، کولاجنېز او نور لري.')
add('Tidbit','مختصر معلومات','لنډ معلومات','heading')
add('Carboxypeptidase: Carboxypeptidase is an enzyme synthesized in the pancreas and secreted into the small intestine. This enzyme hydrolyzes the first peptide or amide bond at the carboxyl end of proteins and peptides. It has a stronger preference for those amino acids that have aromatic or branched hydrocarbon chains.','کاربوکسی پیپٹیڈیز: کاربوکسی پیپٹیڈیز لبلبے میں بننے والا خامرہ ہے جو چھوٹی آنت میں خارج ہوتا ہے۔ یہ خامرہ پروٹینز اور پیپٹائیڈز کے کاربوکسل سرے پر پہلے پیپٹائیڈ یا امائیڈ بند کو ہائیڈرولائز کرتا ہے۔ یہ ان امائنو ایسڈز کو زیادہ ترجیح دیتا ہے جن کی ارومیٹک یا شاخ دار ہائیڈروکاربن زنجیریں ہوں۔','کاربوکسي پېپټیډېز: کاربوکسي پېپټیډېز په پانقراس کې جوړېدونکی انزایم دی چې کوچنیو کولمو ته افرازېږي. دا انزایم د پروټینونو او پېپټایډونو د کاربوکسیل پای لومړی پېپټایډ یا امایډ تړون هایدرولایز کوي. هغو امینو اسیدونو ته ډېر لومړیتوب ورکوي چې اروماتیک یا څانګه لرونکي هایدروکاربني ځنځیرونه لري.')
add('Elastase: Elastase is an enzyme made by special tissue in the pancreas, an organ in your upper abdomen. Elastase helps break down fats, proteins, and carbohydrates after you eat. It is a key part of your digestive process.','ایلاسٹیز: ایلاسٹیز لبلبے کی خاص بافت سے بننے والا خامرہ ہے، جو پیٹ کے اوپری حصے میں ایک عضو ہے۔ ایلاسٹیز کھانے کے بعد چکنائیوں، پروٹینز اور کاربوہائیڈریٹس کو توڑنے میں مدد دیتا ہے۔ یہ آپ کے ہضم کے عمل کا کلیدی حصہ ہے۔','الاسټېز: الاسټېز یو انزایم دی چې د پانقراس د ځانګړي نسج له خوا جوړېږي، چې ستاسو د ګېډې په پورتنۍ برخه کې یو غړی دی. الاسټېز له خوړلو وروسته د غوړیو، پروټینونو او کاربوهایدرېټونو په ماتولو کې مرسته کوي. دا ستاسو د هضم د عملیې کلیدي برخه ده.')
add('Collagenases: Collagenases are enzymes that break the peptide bonds in collagen. They assist in destroying extracellular structures in the pathogenesis of bacteria.','کولیجینیزز: کولیجینیزز وہ خامرے ہیں جو کولیجن میں پیپٹائیڈ بندوں کو توڑتے ہیں۔ یہ بیکٹیریا کی بیماری پیدا کرنے کے عمل میں خلیوں سے باہر کی ساختوں کو تباہ کرنے میں مدد دیتے ہیں۔','کولاجنېزونه: کولاجنېزونه هغه انزایمونه دي چې په کولاجن کې پېپټایډ تړونونه ماتوي. د باکتریاوو د ناروغۍ جوړونې په عملیه کې د حجرو بهر جوړښتونو په ویجاړولو کې مرسته کوي.')
add('21.3.2 Factors Affecting Enzyme Activity','21.3.2 خامروں کی سرگرمی پر اثر انداز ہونے والے عوامل','21.3.2 د انزایم پر فعالیت اغېزمن عوامل','heading')
add('Several factors that affect the activity of enzyme, such as temperature, pH, enzyme concentration, substrate concentration and the presence of any inhibitor or activator.','کئی عوامل خامرے کی سرگرمی پر اثر انداز ہوتے ہیں، جیسے درجہ حرارت، pH، خامرے کا ارتکاز، سبسٹریٹ کا ارتکاز اور کسی روکنے والے یا فعال کرنے والے کی موجودگی۔','ډېر عوامل د انزایم پر فعالیت اغېز کوي، لکه تودوخه، pH، د انزایم غلظت، د سبسټرېټ غلظت او د کوم مخنیوونکي یا فعالوونکي شتون.')
add('1. Effect of Temperature','1. درجہ حرارت کا اثر','1. د تودوخې اغېز','heading')
add('The protein nature of the enzymes makes them extremely sensitive to thermal changes. Enzyme activity occurs within a narrow range of temperatures compared to ordinary chemical reactions. Each enzyme has a certain temperature at which it is more active and shows maximum activity. This temperature is called the optimum temperature. For most animal enzymes, optimum temperature is around body temperature (37°C). Some plants enzymes such as urease has optimum temperature even upto 60°C. The enzyme activity gradually lowers as the temperature rises more than the optimum temperature until it reaches a certain temperature at which the enzyme activity stops completely due to the change of its natural structure and composition (denaturation of enzyme). On the other hand, if the temperature lowers below the optimum temperature, the enzyme activity decreases until the enzyme reaches at a minimum temperature at which the enzyme activity is the least. The enzyme activity stops completely at 0C°, but if the temperature rises again, the enzyme is reactivated again. Enzymes can be stored for years in frozen state. If we plot a graph between temperature and rate of enzymatic reaction, we get the curve as shown in the Figure 21.3.',
 'خامروں کی پروٹینی نوعیت انہیں حرارتی تبدیلیوں کے لیے انتہائی حساس بناتی ہے۔ عام کیمیائی تعاملات کے مقابلے میں خامروں کی سرگرمی درجہ حرارت کی تنگ حد میں ہوتی ہے۔ ہر خامرے کا ایک خاص درجہ حرارت ہوتا ہے جس پر وہ زیادہ فعال ہوتا ہے اور زیادہ سے زیادہ سرگرمی دکھاتا ہے۔ اس درجہ حرارت کو موزوں ترین درجہ حرارت کہتے ہیں۔ زیادہ تر حیوانی خامروں کے لیے موزوں ترین درجہ حرارت جسم کے درجہ حرارت (37°C) کے قریب ہے۔ یوریز جیسے بعض نباتاتی خامروں کا موزوں ترین درجہ حرارت 60°C تک بھی ہوتا ہے۔ درجہ حرارت موزوں ترین سے بڑھنے پر خامرے کی سرگرمی بتدریج کم ہوتی ہے یہاں تک کہ ایک خاص درجہ حرارت پر قدرتی ساخت اور ترکیب کی تبدیلی (خامرے کی ڈی نیچریشن) کی وجہ سے خامرے کی سرگرمی مکمل طور پر رک جاتی ہے۔ دوسری طرف اگر درجہ حرارت موزوں ترین سے کم ہو تو خامرے کی سرگرمی کم ہوتی جاتی ہے یہاں تک کہ خامرہ ایک کم سے کم درجہ حرارت پر پہنچ جاتا ہے جس پر سرگرمی سب سے کم ہوتی ہے۔ 0C° پر خامرے کی سرگرمی مکمل رک جاتی ہے، لیکن درجہ حرارت دوبارہ بڑھنے پر خامرہ پھر فعال ہو جاتا ہے۔ خامروں کو منجمد حالت میں برسوں تک محفوظ رکھا جا سکتا ہے۔ اگر ہم درجہ حرارت اور خامری تعامل کی شرح کے درمیان گراف بنائیں تو شکل 21.3 جیسا خم حاصل ہوتا ہے۔',
 'د انزایمونو پروټیني طبیعت دوی د تودوخې بدلونونو ته ډېر حساس کوي. د عادي کیمیاوي تعاملونو په پرتله د انزایم فعالیت د تودوخې په یوه تنګه پوله کې ترسره کېږي. هر انزایم یوه ټاکلې تودوخه لري چې پکې ډېر فعال وي او اعظمي فعالیت ښيي. دې تودوخې ته غوره تودوخه وايي. د ډېری حیواني انزایمونو لپاره غوره تودوخه د بدن تودوخې (37°C) ته نږدې ده. ځینې نباتي انزایمونه لکه یوریېز تر 60°C پورې غوره تودوخه لري. کله چې تودوخه له غوره تودوخې لوړه شي، د انزایم فعالیت ورو ورو کمېږي تر دې چې یوې ټاکلې تودوخې ته ورسېږي چې پکې د طبیعي جوړښت او ترکیب د بدلون (د انزایم ډینېچرېشن) له امله د انزایم فعالیت په بشپړ ډول دریږي. له بلې خوا، که تودوخه له غوره تودوخې ټیټه شي، د انزایم فعالیت کمېږي تر دې چې انزایم لږترلږه تودوخې ته ورسېږي چې پکې فعالیت تر ټولو لږ وي. په 0C° کې د انزایم فعالیت بشپړ دریږي، خو که تودوخه بیا لوړه شي، انزایم بیا فعالېږي. انزایمونه په کنګل حالت کې د کلونو لپاره ساتل کېدای شي. که د تودوخې او د انزایمي تعامل د کچې ترمنځ ګراف رسم کړو، هغه منحني لاسته راځي چې په شکل 21.3 کې ښودل شوې.')
